<script setup>
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { api, errorMessage, filterParams, localTime } from './api'

const user = ref(null), checking = ref(true), busy = ref(false), error = ref(''), message = ref('')
const tab = ref('Overview'), overview = ref({}), rows = ref([]), page = ref(1), lastPage = ref(1), total = ref(0)
const people = ref([]), devices = ref([]), selectedImage = ref(null), showCreate = ref(false)
const login = reactive({ email: '', password: '' })
const newUser = reactive({ name: '', email: '', password: '', role: 'employee' })
const policy = reactive({}), storage = ref(''), filters = reactive({ user_id: '', device_id: '', app: '', search: '', from: '', to: '' })
const isAdmin = computed(() => user.value?.role === 'super_admin')
const navigation = computed(() => isAdmin.value ? ['Overview', 'Screenshots', 'Activity', 'Employees', 'Devices', 'Policy', 'Audit log'] : ['Overview', 'Screenshots', 'Activity', 'Devices'])
const titles = { Overview: 'A clear view of your team', Screenshots: 'Screenshot review', Activity: 'Application activity', Employees: 'People & access', Devices: 'Connected devices', Policy: 'Monitoring policy', 'Audit log': 'Access & changes' }
const descriptions = { Overview: 'Device health and recent capture activity, in one place.', Screenshots: 'Review captured screens by person, device, and time.', Activity: 'Search foreground applications and window titles.', Employees: 'Manage employees, reviewers, and administrators.', Devices: 'Enrollment, connection status, and device controls.', Policy: 'Settings are distributed to enrolled agents by the server.', 'Audit log': 'A record of who accessed data and changed settings.' }
let poll, generation = 0
function clearMessages() { error.value = ''; message.value = '' }
function handleError(err) { if (err.response?.status === 401) user.value = null; error.value = errorMessage(err) }
async function signIn() { busy.value = true; clearMessages(); try { await api.get('/sanctum/csrf-cookie'); user.value = (await api.post('/api/admin/login', login)).data.user; login.password = ''; await initialize() } catch (err) { handleError(err) } finally { busy.value = false } }
async function signOut() { try { await api.post('/api/admin/logout'); user.value = null; rows.value = []; selectedImage.value = null } catch (err) { handleError(err) } }
async function initialize() { const result = await api.get('/api/admin/options'); people.value = result.data.users; devices.value = result.data.devices; await load() }
async function load() {
  if (!user.value) return
  const current = ++generation; busy.value = true; error.value = ''
  try {
    if (tab.value === 'Overview') { const result = await api.get('/api/admin/overview'); if (current === generation) overview.value = result.data }
    else if (tab.value === 'Policy') { const result = await api.get('/api/admin/policy'); if (current === generation) { Object.assign(policy, result.data.policy); storage.value = result.data.storage } }
    else { const endpoints = { Screenshots: 'screenshots', Activity: 'activity', Employees: 'users', Devices: 'devices', 'Audit log': 'audit' }; const result = await api.get('/api/admin/' + endpoints[tab.value], { params: { ...filterParams(filters), page: page.value } }); if (current === generation) { rows.value = result.data.data; lastPage.value = result.data.last_page; total.value = result.data.total } }
  } catch (err) { if (current === generation) handleError(err) } finally { if (current === generation) busy.value = false }
}
watch(tab, () => { page.value = 1; rows.value = []; selectedImage.value = null; clearMessages(); load() })
async function applyFilters() { page.value = 1; await load() }
async function changePage(delta) { page.value += delta; await load() }
async function createUser() { busy.value = true; clearMessages(); try { await api.post('/api/admin/users', newUser); showCreate.value = false; Object.assign(newUser, { name: '', email: '', password: '', role: 'employee' }); message.value = 'Account created. Share the initial password through your approved channel.'; await initialize() } catch (err) { handleError(err) } finally { busy.value = false } }
async function toggleUser(person) { if (!confirm(`${person.enabled ? 'Disable' : 'Enable'} ${person.name}? Disabling also revokes device access.`)) return; clearMessages(); try { await api.patch(`/api/admin/users/${person.id}`, { enabled: !person.enabled }); await initialize() } catch (err) { handleError(err) } }
async function changeDevice(device, changes) { clearMessages(); try { await api.patch(`/api/admin/devices/${device.id}`, changes); message.value = 'Device policy updated. Online agents receive changes on their next heartbeat.'; await load() } catch (err) { handleError(err) } }
async function savePolicy() { busy.value = true; clearMessages(); try { Object.assign(policy, (await api.put('/api/admin/policy', policy)).data.policy); message.value = 'Policy saved. Online agents refresh within 30 seconds.' } catch (err) { handleError(err) } finally { busy.value = false } }
async function checkStorage() { busy.value = true; clearMessages(); try { message.value = (await api.post('/api/admin/storage-check')).data.message } catch (err) { handleError(err) } finally { busy.value = false } }
async function exportCSV() { clearMessages(); try { const response = await api.get('/api/admin/activity/export', { params: filterParams(filters), responseType: 'blob' }); const url = URL.createObjectURL(response.data); const link = document.createElement('a'); link.href = url; link.download = 'activity.csv'; link.click(); URL.revokeObjectURL(url); message.value = 'Export downloaded. This access has been logged.' } catch (err) { handleError(err) } }
function imageStep(direction) { const index = rows.value.findIndex(item => item.id === selectedImage.value?.id); if (rows.value[index + direction]) selectedImage.value = rows.value[index + direction] }
function keyboard(event) { if (event.key === 'Escape') { selectedImage.value = null; showCreate.value = false } }
onMounted(async () => { window.addEventListener('keydown', keyboard); try { user.value = (await api.get('/api/admin/me')).data.user; await initialize() } catch (err) { if (err.response?.status !== 401) handleError(err) } finally { checking.value = false }; poll = setInterval(() => { if (user.value && tab.value === 'Overview' && !busy.value) load() }, 30000) })
onUnmounted(() => { clearInterval(poll); window.removeEventListener('keydown', keyboard) })
</script>

<template>
  <div v-if="checking" class="loading-screen">Loading Activity…</div>
  <div v-else-if="!user" class="login-layout">
    <section class="login-story"><div class="brand"><span class="brand-symbol">a</span> activity<span class="brand-dot">.</span></div><div><div class="eyebrow light">TEAM VISIBILITY, WITH CONTEXT</div><h1>Know what’s happening.<br><em>Keep trust in view.</em></h1><p>A shared workspace for device health, captured screens, and application activity. Clear policies. Controlled access.</p></div><small>Administrator workspace · All data access is recorded</small></section>
    <main class="login-form"><div class="eyebrow">WELCOME BACK</div><h2>Sign in to your workspace</h2><p class="muted">Use your administrator or reviewer account.</p><form @submit.prevent="signIn"><label>Email address<input v-model.trim="login.email" type="email" autocomplete="username" placeholder="you@company.com" required></label><label>Password<input v-model="login.password" type="password" autocomplete="current-password" required></label><div v-if="error" class="notice danger" role="alert">{{ error }}</div><button class="primary full" :disabled="busy">{{ busy ? 'Signing in…' : 'Sign in →' }}</button></form><p class="small muted">Employee? Sign in through the installed desktop agent. Accounts are provisioned by your administrator.</p></main>
  </div>
  <div v-else class="app-shell">
    <aside class="sidebar"><div class="brand"><span class="brand-symbol">a</span> activity<span class="brand-dot">.</span></div><div class="nav-caption">WORKSPACE</div><nav><button v-for="(item,index) in navigation" :key="item" :class="{ selected: tab === item }" @click="tab = item"><span class="nav-icon">{{ ['◫','▧','≋','♙','▣','⚙','☷'][index] }}</span>{{ item }}</button></nav><div class="sidebar-footer"><div class="avatar">{{ user.name[0] }}</div><div><strong>{{ user.name }}</strong><small>{{ user.role === 'super_admin' ? 'Super admin' : 'Reviewer' }}</small></div><button class="signout" title="Sign out" aria-label="Sign out" @click="signOut">↗</button></div></aside>
    <main class="workspace"><header class="topbar"><span>Workspace <span class="crumb">/ {{ tab }}</span></span><span class="secure-badge">● Private workspace</span></header><div class="page-content"><div class="page-heading"><div><div class="eyebrow">{{ tab === 'Overview' ? 'WORKSPACE OVERVIEW' : 'TEAM ACTIVITY' }}</div><h1>{{ titles[tab] }}</h1><p class="muted">{{ descriptions[tab] }}</p></div><div class="heading-actions"><button v-if="tab === 'Employees' && isAdmin" class="primary" @click="showCreate = true">＋ Add account</button><button v-if="tab === 'Activity'" @click="exportCSV">Export CSV ↗</button><button :disabled="busy" @click="load">{{ busy ? 'Loading…' : '↻ Refresh' }}</button></div></div>
    <div v-if="error" class="notice danger" role="alert">{{ error }}</div><div v-if="message" class="notice success" role="status">{{ message }}</div>
    <template v-if="tab === 'Overview'"><div class="stats-grid"><article class="stat"><span>Enrolled devices</span><strong>{{ overview.devices ?? '—' }}</strong><small>Across your workspace</small></article><article class="stat"><span>Online now</span><strong class="teal">{{ overview.online ?? '—' }}</strong><small>Heartbeat within two minutes</small></article><article class="stat"><span>Screenshots today</span><strong>{{ overview.screenshots_today ?? '—' }}</strong><small>UTC calendar day</small></article><article class="stat"><span>Active employees</span><strong>{{ overview.employees ?? '—' }}</strong><small>Enabled employee accounts</small></article></div><div class="overview-grid"><section class="card"><div class="card-heading"><h2>Device health</h2><button class="text-button" @click="tab = 'Devices'">View devices →</button></div><div v-if="!overview.recent_devices?.length" class="empty-state"><span>▣</span><h3>Your first device starts here</h3><p>Create an employee account, configure the desktop agent, and sign in to enroll it.</p></div><div v-for="device in overview.recent_devices" :key="device.id" class="device-row"><div class="device-icon">▣</div><div class="grow"><strong>{{ device.name }}</strong><small>{{ device.user?.name }} · {{ device.os }}</small></div><span class="pill" :class="device.online ? 'green' : 'neutral'">{{ device.online ? 'Online' : 'Offline' }}</span></div></section><section class="card"><div class="card-heading"><h2>Frequently sampled apps</h2><span class="small muted">Today, UTC</span></div><div v-if="!overview.apps?.length" class="empty-state compact"><span>≋</span><h3>No activity yet</h3><p>Applications appear after an enrolled agent starts sending samples.</p></div><div v-for="app in overview.apps" :key="app.app_name" class="app-bar"><div><strong>{{ app.app_name }}</strong><span>{{ app.samples }} samples</span></div><div class="bar-track"><div :style="{width: Math.max(3,100*app.samples/(overview.apps[0]?.samples||1))+'%'}"></div></div></div><p class="footnote">Samples indicate the foreground app. They do not measure productivity or idle time.</p></section></div></template>
    <form v-if="['Screenshots','Activity'].includes(tab)" class="filter-bar" @submit.prevent="applyFilters"><label>Employee<select v-model="filters.user_id"><option value="">All employees</option><option v-for="person in people" :value="person.id" :key="person.id">{{ person.name }}</option></select></label><label>Device<select v-model="filters.device_id"><option value="">All devices</option><option v-for="device in devices" :value="device.id" :key="device.id">{{ device.name }}</option></select></label><label>From (UTC)<input v-model="filters.from" type="date"></label><label>Through (UTC)<input v-model="filters.to" type="date"></label><label>Application<input v-model="filters.app" placeholder="chrome.exe"></label><label v-if="tab === 'Activity'">Title contains<input v-model="filters.search" placeholder="Search window titles"></label><button class="primary" :disabled="busy">Apply</button></form>
    <template v-if="tab === 'Screenshots'"><div v-if="!rows.length" class="card empty-state"><span>▧</span><h3>{{ busy ? 'Loading captures…' : 'No screenshots in this view' }}</h3><p>Try another date or employee. New captures appear after the agent uploads them.</p></div><div v-else class="gallery"><button v-for="item in rows" :key="item.id" class="capture-card" @click="selectedImage = item"><div class="capture-preview"><img :src="item.thumbnail_url" :alt="'Screenshot from '+item.user_name" loading="lazy"><span>{{ item.app_name || 'Desktop' }}</span></div><div class="capture-info"><strong>{{ item.user_name }}</strong><small>{{ localTime(item.captured_at) }}</small><p>{{ item.device_name }}</p></div></button></div></template>
    <section v-if="['Activity','Employees','Devices','Audit log'].includes(tab)" class="card table-card"><div class="table-scroll"><table><thead><tr v-if="tab === 'Activity'"><th>Captured</th><th>Employee / device</th><th>Application</th><th>Window title</th><th>Browser address</th></tr><tr v-if="tab === 'Employees'"><th>Person</th><th>Role</th><th>Status</th><th>Created</th><th></th></tr><tr v-if="tab === 'Devices'"><th>Device</th><th>Employee</th><th>Status</th><th>Last seen / uploaded</th><th v-if="isAdmin">Controls</th></tr><tr v-if="tab === 'Audit log'"><th>When</th><th>Actor</th><th>Action</th><th>Subject</th><th>IP address</th></tr></thead><tbody><tr v-if="!rows.length"><td colspan="5" class="empty-cell">{{ busy ? 'Loading…' : 'No records found.' }}</td></tr><template v-for="item in rows" :key="item.id"><tr v-if="tab === 'Activity'"><td>{{ localTime(item.captured_at) }}</td><td><strong>{{ item.user_name }}</strong><small>{{ item.device_name }}</small></td><td><span class="app-label">{{ item.app_name }}</span></td><td class="wrap">{{ item.window_title }}</td><td class="wrap muted">{{ item.url || '—' }}</td></tr><tr v-if="tab === 'Employees'"><td><strong>{{ item.name }}</strong><small>{{ item.email }}</small></td><td>{{ item.role.replaceAll('_',' ') }}</td><td><span class="pill" :class="item.enabled ? 'green' : 'neutral'">{{ item.enabled ? 'Enabled' : 'Disabled' }}</span></td><td>{{ localTime(item.created_at) }}</td><td><button v-if="item.id !== user.id" class="small-button" @click="toggleUser(item)">{{ item.enabled ? 'Disable' : 'Enable' }}</button></td></tr><tr v-if="tab === 'Devices'"><td><strong>{{ item.name }}</strong><small class="mono">{{ item.device_identifier }}</small></td><td>{{ item.user?.name }}</td><td><span class="pill" :class="item.disabled_at ? 'neutral' : item.paused ? 'amber' : item.online ? 'green' : 'neutral'">{{ item.disabled_at ? 'Disabled' : item.paused ? 'Paused by admin' : item.online ? 'Online' : 'Offline' }}</span></td><td>{{ localTime(item.last_seen_at) }}<small>Upload: {{ localTime(item.last_upload_at) }}</small></td><td v-if="isAdmin"><div class="inline-actions"><button class="small-button" @click="changeDevice(item,{paused:!item.paused})">{{ item.paused ? 'Resume' : 'Pause' }}</button><button class="small-button" @click="changeDevice(item,{enabled:!!item.disabled_at})">{{ item.disabled_at ? 'Enable' : 'Disable' }}</button></div></td></tr><tr v-if="tab === 'Audit log'"><td>{{ localTime(item.created_at) }}</td><td>{{ item.actor?.name || 'System / former user' }}</td><td><span class="app-label">{{ item.action }}</span></td><td class="wrap mono">{{ item.subject_type }} {{ item.subject_id }}</td><td class="mono">{{ item.ip_address || '—' }}</td></tr></template></tbody></table></div></section>
    <section v-if="tab === 'Policy'" class="policy-layout"><form class="card policy-form" @submit.prevent="savePolicy"><h2>Capture policy</h2><p class="muted">Agents read this policy at login and on each heartbeat.</p><label class="check-label"><input v-model="policy.monitoring_enabled" type="checkbox">Enable monitoring for enrolled devices</label><div class="form-grid"><label>Screenshot period (seconds)<input v-model.number="policy.screenshot_interval_seconds" type="number" min="30" max="3600" required><small>One random capture within each period.</small></label><label>Activity sampling (seconds)<input v-model.number="policy.activity_interval_seconds" type="number" min="5" max="300" required></label><label>Screenshot / activity retention (days)<input v-model.number="policy.retention_days" type="number" min="1" max="365" required></label><label>Audit log retention (days)<input v-model.number="policy.audit_retention_days" type="number" min="30" max="3650" required></label><label>Offline storage limit (MB per device)<input v-model.number="policy.offline_queue_max_mb" type="number" min="50" max="10240" required></label><label>Offline queue retention (days)<input v-model.number="policy.offline_retention_days" type="number" min="1" max="30" required></label></div><label class="check-label"><input v-model="policy.browser_urls" type="checkbox">Collect supported browser addresses (site and path only)</label><label>Employee monitoring notice<textarea v-model="policy.notice" rows="5" required minlength="20" maxlength="4000"></textarea><small>Describe the purpose, access, and retention rules for your organization.</small></label><button class="primary" :disabled="busy">Save policy</button></form><aside class="card policy-aside"><h2>Storage & access</h2><span class="pill green">{{ storage === 'ftps' ? 'FTPS gateway' : 'Private server storage' }}</span><p>Upload destinations and credentials are configured on the server. Agents receive an authenticated upload endpoint.</p><button :disabled="busy" @click="checkStorage">Check storage connection</button><hr><h3>Role boundaries</h3><p><strong>Super admin</strong><br>Manage accounts, policies, devices, and audit logs.</p><p><strong>Reviewer</strong><br>Review screenshots and activity, and export CSV.</p><p class="small muted">Retention settings are organizational policy, not a claim of legal compliance. Run the scheduler to enforce deletion.</p></aside></section>
    <div v-if="!['Overview','Policy'].includes(tab)" class="pagination"><span>{{ total }} records · Page {{ page }} of {{ lastPage }}</span><div><button :disabled="page <= 1 || busy" @click="changePage(-1)">← Previous</button><button :disabled="page >= lastPage || busy" @click="changePage(1)">Next →</button></div></div>
    </div></main>
    <div v-if="showCreate" class="modal-backdrop" @click.self="showCreate = false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="account-title"><div class="card-heading"><h2 id="account-title">Add an account</h2><button aria-label="Close" @click="showCreate = false">×</button></div><form @submit.prevent="createUser"><label>Full name<input v-model.trim="newUser.name" required maxlength="120"></label><label>Email<input v-model.trim="newUser.email" type="email" required></label><label>Role<select v-model="newUser.role"><option value="employee">Employee</option><option value="reviewer">Reviewer</option><option value="super_admin">Super admin</option></select></label><label>Initial password<input v-model="newUser.password" type="password" minlength="12" autocomplete="new-password" required><small>At least 12 characters.</small></label><p v-if="error" class="notice danger">{{ error }}</p><button class="primary full" :disabled="busy">Create account</button></form></section></div>
    <div v-if="selectedImage" class="modal-backdrop image-backdrop" @click.self="selectedImage = null"><section class="image-modal" role="dialog" aria-modal="true" aria-label="Screenshot detail"><div class="image-toolbar"><div><strong>{{ selectedImage.user_name }} · {{ selectedImage.device_name }}</strong><small>{{ localTime(selectedImage.captured_at) }} · {{ selectedImage.app_name || 'Desktop' }}</small></div><div class="inline-actions"><button @click="imageStep(-1)">← Previous</button><button @click="imageStep(1)">Next →</button><button aria-label="Close screenshot" @click="selectedImage = null">×</button></div></div><img :src="selectedImage.image_url" :alt="'Full screenshot from '+selectedImage.user_name"><p>{{ selectedImage.window_title }}</p></section></div>
  </div>
</template>
